-- Migration 028: Platform-wide append-only audit events + invoice correlation id.
-- Postgres. Application code INSERT-only; no UPDATE/DELETE path for audit rows.

CREATE SEQUENCE IF NOT EXISTS "ESSA_AUDIT_EVENT_ID_SEQ" START WITH 100001 INCREMENT BY 1;

CREATE TABLE IF NOT EXISTS "ESSA_AUDIT_EVENT" (
  "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "EventId" VARCHAR(40) NOT NULL,
  "EventTime" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  "Action" VARCHAR(40) NOT NULL,
  "FieldCode" VARCHAR(80) NULL,
  "OldValue" TEXT NULL,
  "NewValue" TEXT NULL,
  "ActorId" VARCHAR(80) NULL,
  "ActorName" VARCHAR(200) NULL,
  "ActorRole" VARCHAR(80) NULL,
  "ActorType" VARCHAR(20) NOT NULL DEFAULT 'USER',
  "ReasonRemarks" TEXT NULL,
  "Source" VARCHAR(40) NOT NULL DEFAULT 'PORTAL',
  "CorrelationId" VARCHAR(80) NULL,
  "Result" VARCHAR(40) NOT NULL DEFAULT 'SUCCESS',
  "ObjectType" VARCHAR(40) NOT NULL,
  "ObjectId" VARCHAR(120) NOT NULL,
  "InvoiceId" INTEGER NULL,
  "Ip" VARCHAR(80) NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS "UX_ESSA_AUDIT_EVENT_EventId"
  ON "ESSA_AUDIT_EVENT" ("EventId");

CREATE INDEX IF NOT EXISTS "IX_ESSA_AUDIT_EVENT_EventTime"
  ON "ESSA_AUDIT_EVENT" ("EventTime" DESC);

CREATE INDEX IF NOT EXISTS "IX_ESSA_AUDIT_EVENT_Object"
  ON "ESSA_AUDIT_EVENT" ("ObjectType", "ObjectId", "EventTime" DESC);

CREATE INDEX IF NOT EXISTS "IX_ESSA_AUDIT_EVENT_Action"
  ON "ESSA_AUDIT_EVENT" ("Action");

CREATE INDEX IF NOT EXISTS "IX_ESSA_AUDIT_EVENT_ActorId"
  ON "ESSA_AUDIT_EVENT" ("ActorId");

CREATE INDEX IF NOT EXISTS "IX_ESSA_AUDIT_EVENT_CorrelationId"
  ON "ESSA_AUDIT_EVENT" ("CorrelationId");

CREATE INDEX IF NOT EXISTS "IX_ESSA_AUDIT_EVENT_InvoiceId"
  ON "ESSA_AUDIT_EVENT" ("InvoiceId", "EventTime" DESC);

CREATE INDEX IF NOT EXISTS "IX_ESSA_AUDIT_EVENT_FieldCode"
  ON "ESSA_AUDIT_EVENT" ("FieldCode")
  WHERE "FieldCode" IS NOT NULL;

ALTER TABLE "ESSA_INVOICE"
  ADD COLUMN IF NOT EXISTS "CorrelationId" VARCHAR(80) NULL;

CREATE INDEX IF NOT EXISTS "IX_ESSA_INVOICE_CorrelationId"
  ON "ESSA_INVOICE" ("CorrelationId")
  WHERE "CorrelationId" IS NOT NULL;
